import{_ as p,a0 as o,w as d,s as r,ao as l,I as a,a1 as t,A as e,x as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"3 个简单、优秀的 Linux 网络监视器 | LCTT x X-CMD","titleTemplate":false,"description":"3 个简单、优秀的 Linux 网络监视器 | LCTT (201711) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"3 个简单、优秀的 Linux 网络监视器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"3 个简单、优秀的 Linux 网络监视器 | LCTT (201711) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201711/20171019 3 Simple Excellent Linux Network Monitors","title":"3 个简单、优秀的 Linux 网络监视器","tag":"201711","desc":""},"relativePath":"201711/20171019 3 Simple Excellent Linux Network Monitors.md","filePath":"[post].md"}'),g={name:"201711/20171019 3 Simple Excellent Linux Network Monitors.md"};function h(u,s,k,c,b,f){const i=o("Link");return d(),r("div",null,[s[31]||(s[31]=l('<h1 id="_3-个简单、优秀的-linux-网络监视器" tabindex="-1">3 个简单、优秀的 Linux 网络监视器 <a class="header-anchor" href="#_3-个简单、优秀的-linux-网络监视器" aria-label="Permalink to “3 个简单、优秀的 Linux 网络监视器”">​</a></h1><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/banner_3.png?itok=iuPcSN4k" alt="network" title="network"></p><p><em>用 iftop、Nethogs 和 vnstat 了解更多关于你的网络连接。</em></p><p>你可以通过这三个 Linux 网络命令，了解有关你网络连接的大量信息。iftop 通过进程号跟踪网络连接，Nethogs 可以快速显示哪个在占用你的带宽，而 vnstat 作为一个很好的轻量级守护进程运行，可以随时随地记录你的使用情况。</p><h3 id="iftop" tabindex="-1">iftop <a class="header-anchor" href="#iftop" aria-label="Permalink to “iftop”">​</a></h3>',5)),a("p",null,[t(i,{href:"http://www.ex-parrot.com/pdw/iftop/"},{default:e(()=>[...s[0]||(s[0]=[n("iftop",-1)])]),_:1}),s[1]||(s[1]=n(" 监听你指定的网络接口，并以 ",-1)),s[2]||(s[2]=a("code",null,"top",-1)),s[3]||(s[3]=n(" 的形式展示连接。",-1))]),s[32]||(s[32]=l(`<p>这是一个很好的小工具，用于快速识别占用、测量速度，并保持网络流量的总体运行。看到我们使用了多少带宽是非常令人惊讶的，特别是对于我们这些还记得使用电话线、调制解调器、让人尖叫的 Kbit 速度和真实的实时波特率的老年人来说。我们很久以前就放弃了波特率，转而使用比特率。波特率测量信号变化，有时与比特率相同，但大多数情况下不是。</p><p>如果你只有一个网络接口，可以不带选项运行 <code>iftop</code>。<code>iftop</code> 需要 root 权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo iftop</span></span></code></pre></div><p>当你有多个接口时，指定要监控的接口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo iftop -i wlan0</span></span></code></pre></div><p>就像 top 一样，你可以在运行时更改显示选项。</p><ul><li><code>h</code> 切换帮助屏幕。</li><li><code>n</code> 切换名称解析。</li><li><code>s</code> 切换源主机显示，<code>d</code> 切换目标主机。</li><li><code>s</code> 切换端口号。</li><li><code>N</code> 切换端口解析。要全看到端口号，请关闭解析。</li><li><code>t</code> 切换文本界面。默认显示需要 ncurses。我认为文本显示更易于阅读和更好的组织（图1）。</li><li><code>p</code> 暂停显示。</li><li><code>q</code> 退出程序。</li></ul><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/fig-1_8.png?itok=luKHS5ve" alt="text display" title="text display"></p><p><em>图 1：文本显示是可读的和可组织的。</em></p><p>当你切换显示选项时，<code>iftop</code> 会继续测量所有流量。你还可以选择要监控的单个主机。你需要主机的 IP 地址和网络掩码。我很好奇 Pandora 在我那可怜的带宽中占用了多少，所以我先用 <code>dig</code> 找到它们的 IP 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dig A pandora.com</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>;; ANSWER SECTION:</span></span>
<span class="line"><span>pandora.com.            267     IN      A       208.85.40.20</span></span>
<span class="line"><span>pandora.com.            267     IN      A       208.85.40.50</span></span></code></pre></div>`,11)),a("p",null,[s[5]||(s[5]=n("网络掩码是什么？ ",-1)),t(i,{href:"https://www.linux.com/learn/intro-to-linux/2017/8/how-calculate-network-addresses-ipcalc"},{default:e(()=>[...s[4]||(s[4]=[n("ipcalc",-1)])]),_:1}),s[6]||(s[6]=n(" 告诉我们：",-1))]),s[33]||(s[33]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ipcalc -b 208.85.40.20</span></span>
<span class="line"><span>Address:   208.85.40.20   </span></span>
<span class="line"><span>Netmask:   255.255.255.0 = 24</span></span>
<span class="line"><span>Wildcard:  0.0.0.255  </span></span>
<span class="line"><span>=&gt;</span></span>
<span class="line"><span>Network:   208.85.40.0/24</span></span></code></pre></div><p>现在将地址和网络掩码提供给 iftop：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo iftop -F 208.85.40.20/24 -i wlan0</span></span></code></pre></div><p>这不是真的吗？我很惊讶地发现，我珍贵的带宽对于 Pandora 很宽裕，每小时使用大约使用 500Kb。而且，像大多数流媒体服务一样，Pandora 的流量也有峰值，其依赖于缓存来缓解阻塞。</p>`,4)),a("p",null,[s[8]||(s[8]=n("你可以使用 ",-1)),s[9]||(s[9]=a("code",null,"-G",-1)),s[10]||(s[10]=n(" 选项对 IPv6 地址执行相同操作。请参阅手册页了解 ",-1)),s[11]||(s[11]=a("code",null,"iftop",-1)),s[12]||(s[12]=n(" 的其他功能，包括使用自定义配置文件定制默认选项，并应用自定义过滤器（请参阅 ",-1)),t(i,{href:"http://www.tcpdump.org/manpages/pcap-filter.7.html"},{default:e(()=>[...s[7]||(s[7]=[n("PCAP-FILTER",-1)])]),_:1}),s[13]||(s[13]=n(" 作为过滤器参考）。",-1))]),s[34]||(s[34]=l(`<h3 id="nethogs" tabindex="-1">Nethogs <a class="header-anchor" href="#nethogs" aria-label="Permalink to “Nethogs”">​</a></h3><p>当你想要快速了解谁占用了你的带宽时，Nethogs 是快速和容易的。以 root 身份运行，并指定要监听的接口。它显示了空闲的应用程序和进程号，以便如果你愿意的话，你可以杀死它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nethogs wlan0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>NetHogs version 0.8.1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PID USER   PROGRAM              DEV    SENT   RECEIVED       </span></span>
<span class="line"><span>7690 carla /usr/lib/firefox     wlan0 12.494 556.580 KB/sec</span></span>
<span class="line"><span>5648 carla .../chromium-browser wlan0  0.052   0.038 KB/sec</span></span>
<span class="line"><span>TOTAL                                 12.546 556.618 KB/sec</span></span></code></pre></div><p>Nethogs 选项很少：在 kb/s、kb、b 和 mb 之间循环；通过接收或发送的数据包进行排序；并调整刷新之间的延迟。请参阅 <code>man nethogs</code>，或者运行 <code>nethogs -h</code>。</p><h3 id="vnstat" tabindex="-1">vnstat <a class="header-anchor" href="#vnstat" aria-label="Permalink to “vnstat”">​</a></h3>`,5)),a("p",null,[t(i,{href:"http://humdi.net/vnstat/"},{default:e(()=>[...s[14]||(s[14]=[n("vnstat",-1)])]),_:1}),s[15]||(s[15]=n(" 是最容易使用的网络数据收集器。它是轻量级的，不需要 root 权限。它作为守护进程运行，并记录你网络统计信息。",-1)),s[16]||(s[16]=a("code",null,"vnstat",-1)),s[17]||(s[17]=n(" 命令显示累计的数据：",-1))]),s[35]||(s[35]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vnstat -i wlan0</span></span>
<span class="line"><span>Database updated: Tue Oct 17 08:36:38 2017</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   wlan0 since 10/17/2017</span></span>
<span class="line"><span></span></span>
<span class="line"><span>          rx:  45.27 MiB      tx:  3.77 MiB      total:  49.04 MiB</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   monthly</span></span>
<span class="line"><span>                     rx      |     tx      |    total    |   avg. rate</span></span>
<span class="line"><span>     ------------------------+-------------+-------------+---------------</span></span>
<span class="line"><span>       Oct &#39;17     45.27 MiB |    3.77 MiB |   49.04 MiB |    0.28 kbit/s</span></span>
<span class="line"><span>     ------------------------+-------------+-------------+---------------</span></span>
<span class="line"><span>     estimated        85 MiB |       5 MiB |      90 MiB |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   daily</span></span>
<span class="line"><span>                     rx      |     tx      |    total    |   avg. rate</span></span>
<span class="line"><span>     ------------------------+-------------+-------------+---------------</span></span>
<span class="line"><span>         today     45.27 MiB |    3.77 MiB |   49.04 MiB |   12.96 kbit/s</span></span>
<span class="line"><span>     ------------------------+-------------+-------------+---------------</span></span>
<span class="line"><span>     estimated       125 MiB |       8 MiB |     133 MiB |</span></span></code></pre></div><p>它默认显示所有的网络接口。使用 <code>-i</code> 选项选择单个接口。以这种方式合并多个接口的数据：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vnstat -i wlan0+eth0+eth1</span></span></code></pre></div><p>你可以通过以下几种方式过滤显示：</p><ul><li><code>-h</code> 以小时显示统计数据。</li><li><code>-d</code> 以天数显示统计数据。</li><li><code>-w</code> 和 <code>-m</code> 按周和月显示统计数据。</li><li>使用 <code>-l</code> 选项查看实时更新。</li></ul><p>此命令删除 wlan1 的数据库，并停止监控它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vnstat -i wlan1 --delete</span></span></code></pre></div><p>此命令为网络接口创建别名。此例使用 Ubuntu 16.04 中的一个奇怪的接口名称：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vnstat -u -i enp0s25 --nick eth0</span></span></code></pre></div><p>默认情况下，vnstat 监视 eth0。你可以在 <code>/etc/vnstat.conf</code> 中更改此内容，或在主目录中创建自己的个人配置文件。请参见 <code>man vnstat</code> 以获得完整的参考。</p><p>你还可以安装 <code>vnstati</code> 创建简单的彩色图（图2）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vnstati -s -i wlx7cdd90a0a1c2 -o vnstat.png</span></span></code></pre></div><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/fig-2_5.png?itok=HsWJMcW0" alt="vnstati" title="vnstati"></p><p><em>图 2：你可以使用 vnstati 创建简单的彩色图表。</em></p><p>有关完整选项，请参见 <code>man vnstati</code>。</p><hr>`,16)),a("p",null,[s[19]||(s[19]=n("via: ",-1)),t(i,{href:"https://www.linux.com/learn/intro-to-linux/2017/10/3-simple-excellent-linux-network-monitors"},{default:e(()=>[...s[18]||(s[18]=[n("https://www.linux.com/learn/intro-to-linux/2017/10/3-simple-excellent-linux-network-monitors",-1)])]),_:1})]),a("p",null,[s[23]||(s[23]=n("作者：",-1)),t(i,{href:"https://www.linux.com/users/cschroder"},{default:e(()=>[...s[20]||(s[20]=[n("CARLA SCHRODER",-1)])]),_:1}),s[24]||(s[24]=n(" 译者：",-1)),t(i,{href:"https://github.com/geekpi"},{default:e(()=>[...s[21]||(s[21]=[n("geekpi",-1)])]),_:1}),s[25]||(s[25]=n(" 校对：",-1)),t(i,{href:"https://github.com/wxy"},{default:e(()=>[...s[22]||(s[22]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[28]||(s[28]=n("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[26]||(s[26]=[n("LCTT",-1)])]),_:1}),s[29]||(s[29]=n(" 原创编译，",-1)),t(i,{href:"https://linux.cn/"},{default:e(()=>[...s[27]||(s[27]=[n("Linux中国",-1)])]),_:1}),s[30]||(s[30]=n(" 荣誉推出",-1))])])}const v=p(g,[["render",h]]);export{w as __pageData,v as default};
